const WEB_DEMO_ORIGIN=location.hostname==='127.0.0.1'?'http://127.0.0.1:8768':'https://amanus-propuesta-jup-nov26.joseorue.chatgpt.site';
function readWebCandidates(){try{const v=JSON.parse(localStorage.getItem('amanus-web-candidates')||'[]');return Array.isArray(v)?v:[]}catch{return []}}
let webCandidates=readWebCandidates();
function cvDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('amanus-demo-cvs',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function cvStore(action,id,file){const db=await cvDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files',action==='get'?'readonly':'readwrite'),s=tx.objectStore('files');const req=action==='put'?s.put(file,id):action==='clear'?s.clear():s.get(id);let value;req.onsuccess=()=>value=req.result;tx.oncomplete=()=>{db.close();resolve(value)};tx.onerror=()=>{db.close();reject(tx.error)}})}
function generatedCV(c){return `<!doctype html><html lang="es"><meta charset="utf-8"><title>CV ficticio · ${escape(c.name)}</title><style>body{font:16px/1.8 Arial;max-width:760px;margin:45px auto;padding:25px;color:#203a4b}h1{font-size:34px}h2{border-bottom:1px solid #ccdfe3}small{color:#607980}</style><p>CV FICTICIO · DEMO AMANUS</p><h1>${escape(c.name)}</h1><p>${escape(c.job)}<br>${escape(c.city)} · ${escape(c.email)}</p><h2>Presentación</h2><p>${escape(c.message||'Perfil ficticio creado para recorrer la demostración.')}</p><h2>Formación y experiencia</h2><p>${escape(c.education)}<br>${escape(c.experience)}</p><small>Documento generado para la demo. No representa antecedentes reales.</small></html>`}
async function downloadCandidateCV(id){const c=candidateData().find(x=>x.id===id);if(!c)return;try{let blob,name;if(c.fromWeb&&c.cvName){blob=await cvStore('get',id);if(!blob)throw Error('Archivo no disponible en este navegador');name=c.cvName}else if(c.fromWeb){blob=new Blob([generatedCV(c)],{type:'text/html;charset=utf-8'});name=id+'-cv-demo.html'}else{const a=document.createElement('a');a.href='cvs/'+id+'-cv-demo.html';a.download='';a.click();return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch{toast('No se pudo abrir el CV guardado. Volvé a simular la postulación.')}}
const receivingApplications=new Set();
window.addEventListener('message',async event=>{
 const m=event.data;if(event.origin!==WEB_DEMO_ORIGIN||!event.source||!m||m.channel!=='amanus-demo-v1'||typeof m.token!=='string'||m.token.length>100)return;
 const respond=(type,extra={})=>event.source.postMessage({channel:'amanus-demo-v1',type,token:m.token,...extra},WEB_DEMO_ORIGIN);
 if(m.type==='hello'){respond('ready');return}if(m.type!=='application')return;
 const raw=m.payload;if(!raw||typeof raw.id!=='string'||!/^web-[a-f0-9-]{36}$/.test(raw.id)){respond('error',{message:'La postulación no tiene un identificador válido.'});return}
 if(receivingApplications.has(raw.id))return;
 receivingApplications.add(raw.id);
 try{
  webCandidates=readWebCandidates();
  if(!webCandidates.some(c=>c.id===raw.id)){
   const text=(v,n)=>typeof v==='string'?v.trim().slice(0,n):'';
   const name=text(raw.name,100),email=text(raw.email,150),city=text(raw.city,100),job=text(raw.job,180),message=text(raw.message,1500);
   if(!name||!email||!city||!job)throw Error('Faltan datos de la postulación.');
   const file=raw.file;
   if(file&&(!(file instanceof Blob)||file.size>2*1024*1024||typeof file.name!=='string'||!(/\.(pdf|doc|docx)$/i.test(file.name))))throw Error('CV inválido: usá un archivo de ejemplo de hasta 2 MB.');
   if(webCandidates.length>=100)throw Error('La demo llegó a 100 postulaciones. Reiniciala para seguir probando.');
   const c={id:raw.id,name,email,city,job,message,phone:text(raw.phone,40),status:'Nueva',education:'Formación ficticia para la demostración',skills:'Perfil recibido desde el formulario web',experience:message||'Experiencia de ejemplo pendiente de completar',date:new Intl.DateTimeFormat('es-AR',{timeZone:'America/Argentina/Buenos_Aires'}).format(new Date()),fromWeb:true,cvName:file?text(file.name,200):'',source:'Formulario web · demo'};
   if(file)await cvStore('put',c.id,file);
   webCandidates=[c,...readWebCandidates()];localStorage.setItem('amanus-web-candidates',JSON.stringify(webCandidates));
  }
  candidateQuery='';candidateStatus='';candidateJob='';location.hash='postulaciones';render();candidateProfile(raw.id);toast('Nueva postulación recibida desde la web.');respond('saved',{id:raw.id});
 }catch(error){respond('error',{message:error.message||'No se pudo guardar en este navegador.'})}finally{receivingApplications.delete(raw.id)}
});
